import { useEffect, useState } from "react";
import { Box, Button, Container, Stack, Typography } from "@mui/material";
import api, { mediaUrl } from "../services/api";
import type { HomeBanner, ListResponse } from "../types/home";

const BLUE = "#759ae1";

export default function Carousel() {
  const [slides, setSlides] = useState<HomeBanner[]>([]);
  const [index, setIndex] = useState(0);

  useEffect(() => {
    api
      .get<ListResponse<HomeBanner>>("/home-banners", {
        params: {
          "sort[0]": "order:asc",
          "populate[features]": true,
          "populate[background]": true,
          "populate[bannerImage]": true,
          "populate[appStoreImage]": true,
          "populate[playStoreImage]": true,
        },
      })
      .then((payload) => setSlides(payload.data || []))
      .catch(() => setSlides([]));
  }, []);

  useEffect(() => {
    if (slides.length < 2) return;
    const timer = window.setInterval(() => {
      setIndex((current) => (current + 1) % slides.length);
    }, 6000);
    return () => window.clearInterval(timer);
  }, [slides.length]);

  const slide = slides[index];
  if (!slide) return null;

  const background = mediaUrl(slide.background);
  const banner = mediaUrl(slide.bannerImage);

  return (
    <Box
      sx={{
        position: "relative",
        minHeight: { xs: 560, md: 520 },
        color: "#fff",
        overflow: "hidden",
        backgroundColor: "#7a9bd7",
        backgroundImage: background ? `url(${background})` : "none",
        backgroundSize: "cover",
        backgroundPosition: "center",
      }}
    >
      <Box sx={{ position: "absolute", inset: 0, backgroundColor: "rgba(122,155,215,0.35)" }} />
      <Container maxWidth="lg" sx={{ position: "relative", py: { xs: 6, md: 10 } }}>
        <Stack direction={{ xs: "column", md: "row" }} alignItems="center" spacing={4}>
          <Box sx={{ flex: 1 }}>
            <Typography sx={{ fontSize: { xs: 28, md: 45 }, fontWeight: 500, lineHeight: 1.15, mb: 2 }}>
              {slide.title}
            </Typography>
            <Typography sx={{ fontSize: { xs: 16, md: 22 }, opacity: 0.9, mb: 2, maxWidth: 600 }}>
              {slide.subtitle}
            </Typography>
            <Box component="ul" sx={{ pl: 2.5, mb: 3 }}>
              {(slide.features || []).map((item) => (
                <Typography key={item.id || item.text} component="li" sx={{ fontSize: 16, mb: 0.5 }}>
                  {item.text}
                </Typography>
              ))}
            </Box>
            {slide.subscribeUrl ? (
              <Button
                variant="contained"
                href={slide.subscribeUrl}
                target="_blank"
                rel="noopener noreferrer"
                sx={{
                  backgroundColor: BLUE,
                  borderRadius: "6px",
                  px: 3,
                  mb: 3,
                  "&:hover": { backgroundColor: "#5f86d4" },
                }}
              >
                {slide.subscribeLabel || "Subscribe"}
              </Button>
            ) : null}
            <Stack direction="row" spacing={2} alignItems="center">
              {slide.appStoreUrl && mediaUrl(slide.appStoreImage) ? (
                <Box
                  component="a"
                  href={slide.appStoreUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <Box component="img" src={mediaUrl(slide.appStoreImage)} alt="App Store" sx={{ height: 40 }} />
                </Box>
              ) : null}
              {slide.playStoreUrl && mediaUrl(slide.playStoreImage) ? (
                <Box
                  component="a"
                  href={slide.playStoreUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  <Box component="img" src={mediaUrl(slide.playStoreImage)} alt="Play Store" sx={{ height: 40 }} />
                </Box>
              ) : null}
            </Stack>
          </Box>
          {banner ? (
            <Box sx={{ flex: 1, textAlign: "center" }}>
              <Box
                component="img"
                src={banner}
                alt={slide.bannerImage?.alternativeText || slide.title}
                sx={{ width: "100%", maxWidth: 480, objectFit: "contain" }}
              />
            </Box>
          ) : null}
        </Stack>
      </Container>
      <Stack direction="row" justifyContent="center" spacing={1} sx={{ position: "relative", pb: 3 }}>
        {slides.map((item, dotIndex) => (
          <Box
            key={item.id || dotIndex}
            onClick={() => setIndex(dotIndex)}
            sx={{
              width: 10,
              height: 10,
              borderRadius: "50%",
              cursor: "pointer",
              backgroundColor: dotIndex === index ? "#fff" : "rgba(255,255,255,0.45)",
            }}
          />
        ))}
      </Stack>
    </Box>
  );
}
